alter table public.properties add column price_period text not null default 'unspecified' check (price_period in ('monthly','yearly','one_time','unspecified')), add column service_charge_period text not null default 'unspecified' check (service_charge_period in ('monthly','yearly','one_time','unspecified')), add column agency_fee_period text not null default 'one_time' check (agency_fee_period in ('monthly','yearly','one_time','unspecified')); update public.properties set price_period='yearly', service_charge_period='yearly', agency_fee_period='one_time' where reference like 'NST-DEMO-%' and reference <> 'NST-DEMO-006';;
